message.content:
{
  "css": ".dialog-content {
  display: flex;
  flex-direction: column;
  gap: var(--content-gap);
  padding: 24px;
}

@media (max-width: 360px) {
  .dialog-content {
    padding: 20px;
  }
}

/* Heading */
.dialog-heading {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--icon-label-gap);
}

.dialog-heading h2 {
  font-size: 22px;
  font-weight: 700;
  line-height: 1.45;
  word-break: keep-all;
  overflow-wrap: break-word;
  margin: 0;
  color: var(--text-primary);
}

#close-booking {
  flex-shrink: 0;
  min-width: 44px;
  height: 44px;
  font-size: 14px;
  font-weight: 600;
  color: var(--text-secondary);
  background: transparent;
  border: none;
  border-radius: 6px;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 0 12px;
}

#close-booking:hover {
  background-color: rgba(0, 0, 0, 0.05);
}

/* Summary / Saved Data */
.booking-summary {
  background-color: #f3f3f5;
  padding: 20px;
  border-radius: 8px;
}

.section-label {
  font-size: 14px;
  font-weight: 500;
  line-height: 1.6;
  color: var(--text-secondary);
  margin-bottom: 8px;
}

.booking-class {
  font-size: 16px;
  font-weight: 700;
  color: var(--text-primary);
  margin: 0 0 4px 0;
}

.booking-price {
  font-size: 14px;
  font-weight: 500;
  color: var(--text-secondary);
  margin: 0;
}

/* Form */
#booking-form {
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.booking-field {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.booking-field label {
  font-size: 15px;
  font-weight: 600;
  color: var(--text-primary);
  line-height: 1.4;
}

.field-control {
  position: relative;
  border: 1px solid #dcdce0;
  border-radius: 6px;
  overflow: hidden; /* Contain focus ring */
}

/* Focus Ring on Wrapper */
.field-control:focus-within {
  outline: 2px solid var(--action-bg);
  outline-offset: -2px; /* Inset effect */
}

/* Native Input/Select Reset */
.field-control input,
.field-control select {
  width: 100%;
  min-width: 0;
  min-height: 48px;
  padding: 12px;
  font-size: 16px;
  font-weight: 500;
  line-height: 1.5;
  border: none;
  background-color: #fff;
  color: var(--text-primary);
  appearance: none;
}

.field-control input::placeholder {
  color: #999;
  font-weight: 400;
}

/* Force Colors for Accessibility */
@media (forced-colors: active) {
  .field-control:focus-within {
    outline-color: Highlight;
  }
  .field-control input,
  .field-control select {
    border: 1px solid CanvasText;
  }
}

/* Error Text */
#storage-error,
#cancel-error {
  font-size: 14px;
  font-weight: 500;
  color: #d32f2f;
  margin: 0;
  padding: 0 4px;
}

/* Actions */
.confirm-booking {
  min-height: 52px;
  width: 100%;
  padding: 16px;
  font-size: 16px;
  font-weight: 700;
  line-height: 1.5;
  color: var(--action-fg);
  background-color: var(--action-bg);
  border: none;
  border-radius: 8px;
  cursor: pointer;
  text-align: center;
  white-space: normal;
}

.confirm-booking:hover {
  opacity: 0.9;
}

#cancel-booking {
  min-width: 44px;
  height: 44px;
  font-size: 14px;
  font-weight: 600;
  color: var(--text-secondary);
  background: transparent;
  border: none;
  border-radius: 6px;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  margin-top: 8px;
}

#cancel-booking:hover {
  background-color: rgba(0, 0, 0, 0.05);
}

/* Confirmation Section */
#confirmation {
  display: flex;
  flex-direction: column;
  gap: var(--content-gap);
}

.confirmation-intro {
  font-size: 15px;
  font-weight: 500;
  color: var(--text-primary);
  margin: 0;
}

#confirmation-details {
  font-size: 14px;
  line-height: 1.6;
  white-space: pre-line;
  word-break: keep-all;
  overflow-wrap: break-word;
  color: var(--text-primary);
  margin: 0;
}

/* Hide form when confirmation is visible (handled by app.js setting hidden, but ensure defaults) */
#booking-form[hidden] {
  display: none;
}

#confirmation[hidden] {
  display: none;
}"
}
